def render_icon_svg(spec: str, size: int) -> bytes:
    svg = (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 14 14" '
        f'width="{size}" height="{size}">'
        f'<path d="{spec}" fill="#ffffff" fill-rule="evenodd"/></svg>'
    )
    png = cairosvg.svg2png(bytestring=svg.encode(), output_width=size, output_height=size)
    with Image.open(__import__("io").BytesIO(png)) as im:
        return im.convert("RGBA").getchannel("A").tobytes()


def build_rings(flash: bool) -> bytes:
    im = Image.new("L", (RINGS_W, RINGS_H), 0)
    draw = ImageDraw.Draw(im)
    for ring in RINGS:
        alpha = 0xFF if flash else ring["idle_alpha"]
        draw.ellipse(ring["box"], outline=alpha, width=ring["width"])
    return im.tobytes()


def build_woodfish() -> bytes:
    with Image.open(WOODFISH_PNG) as src:
        rgba = src.convert("RGBA").resize((WOODFISH_W, WOODFISH_H), Image.LANCZOS)
    px = rgba.load()
    out = bytearray()
    for y in range(WOODFISH_H):
        for x in range(WOODFISH_W):
            r, g, b, a = px[x, y]
            v = ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)
            out += bytes((v >> 8, v & 0xFF, a))  # COLOR_16_SWAP：hi, lo, alpha
    return bytes(out)


def write_lvgl_c(path: Path, name: str, cf_macro: str, w: int, h: int, data: bytes,
                 data_size: int) -> None:
    lines = [
        "// Generated by generate_ewf_images.py; do not hand-edit.",
        '#include "lvgl.h"',
        "",
        "#if 1",
        f"const lv_img_dsc_t {name} = {{",
        "  .header = {",
        f"    .cf = {cf_macro},",
        "    .always_zero = 0,",
        "    .reserved = 0,",
        f"    .w = {w},",
        f"    .h = {h},",
        "  },",
        f"  .data_size = {data_size},",
        "  .data = (const uint8_t[]){",
    ]
    for i in range(0, len(data), 16):
        chunk = data[i:i + 16]
        lines.append("    " + ",".join(f"0x{b:02x}" for b in chunk) + ",")
    lines += ["  },", "};", "#endif", ""]
    path.write_text("\n".join(lines), encoding="utf-8")


def main() -> int:
    if not WOODFISH_PNG.exists():
        print(f"缺少木鱼参考图: {WOODFISH_PNG}", file=sys.stderr)
        return 1
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    decls = ["// Generated by generate_ewf_images.py; do not hand-edit.",
             "#ifndef EWF_UI_IMAGES_H", "#define EWF_UI_IMAGES_H", ""]
    for icon, size in ICON_SIZES.items():
        name = f"ui_img_ic_{icon.replace('-', '_')}"
        data = render_icon_svg(ICONS[icon], size)
        write_lvgl_c(OUT_DIR / f"{name}.c", name, "LV_IMG_CF_ALPHA_8BIT", size, size,
                     data, len(data))
        decls.append(f"extern const lv_img_dsc_t {name};")
        print("RUN", name, size, len(data), "bytes")
    rings_idle = build_rings(False)
    write_lvgl_c(OUT_DIR / "ui_img_rings_idle.c", "ui_img_rings_idle",
                 "LV_IMG_CF_ALPHA_8BIT", RINGS_W, RINGS_H, rings_idle, len(rings_idle))
    rings_flash = build_rings(True)
    write_lvgl_c(OUT_DIR / "ui_img_rings_flash.c", "ui_img_rings_flash",
                 "LV_IMG_CF_ALPHA_8BIT", RINGS_W, RINGS_H, rings_flash, len(rings_flash))
    decls.append("extern const lv_img_dsc_t ui_img_rings_idle;")
    decls.append("extern const lv_img_dsc_t ui_img_rings_flash;")
    print("RUN ui_img_rings_idle", len(rings_idle), "bytes")
    print("RUN ui_img_rings_flash", len(rings_flash), "bytes")
    fish = build_woodfish()
    write_lvgl_c(OUT_DIR / "ui_img_woodfish.c", "ui_img_woodfish",
                 "LV_IMG_CF_TRUE_COLOR_ALPHA", WOODFISH_W, WOODFISH_H, fish, len(fish))
    decls.append("extern const lv_img_dsc_t ui_img_woodfish;")
    print("RUN ui_img_woodfish", len(fish), "bytes")
    decls += ["", "#endif", ""]
    (OUT_DIR / "ui_images.h").write_text("\n".join(decls), encoding="utf-8")
    print("images-only sync OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
